//go:build integration

package store

// Integration suite for app.user_keys (Forgejo #47 increment 3, ADR-024).
//
// This is the increment's falsifiable test: a key generated by the crypto
// process must survive a round trip THROUGH THE REAL STORE, UNDER RLS, and come
// back as the same key — not as a row that merely exists.
//
// The unit suite in internal/pgpkeyd proves the SERVICE refuses a foreign key
// on its own account, using an unfiltered in-memory vault so that the check can
// be deleted and shown to matter. What that suite cannot prove is the other
// half: that PostgreSQL refuses too. That is here, and the two together are why
// neither control is redundant.

import (
	"bytes"
	"context"
	"errors"
	"testing"

	"github.com/oklog/ulid/v2"
)

// The public-key fixture here is realPublicKey (wkd_integration_test.go): a
// genuinely generated key, in the binary representation the column holds.
//
// This suite is about STORAGE — RLS, change_log rows, uniqueness — and a
// stand-in would do for all of that. It uses a real key anyway because the one
// bug this file's fixtures failed to expose was a representation mismatch, and
// a hand-written stand-in cannot expose one: it agrees with whatever the author
// believed the format was, which is the thing under test.

func TestUserKeyRoundTripsUnderRLS(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()
	a, _ := seedTwoUsers(t, h.super)
	s := h.appStore()

	userID := ulid.MustParse(a.ID)
	keyID := NewULID()
	sealed := []byte{0x01, 0x02, 0x03, 0x04, 0x05}
	pub := realPublicKey(t, "fixture@example.com")

	if err := s.UserTx(ctx, userID, func(tx *UserTx) error {
		_, err := tx.InsertUserKey(ctx, UserKey{
			ID:           keyID,
			UserID:       userID,
			Kind:         KeyPGP,
			Fingerprint:  "ABCDEF0123456789",
			PublicKey:    pub,
			PrivateKeyCT: sealed,
		})
		return err
	}); err != nil {
		t.Fatalf("InsertUserKey: %v", err)
	}

	var got UserKey
	if err := s.UserTx(ctx, userID, func(tx *UserTx) error {
		k, found, err := tx.GetUserKey(ctx, keyID)
		if err != nil {
			return err
		}
		if !found {
			t.Fatal("the key was inserted and then not found by its owner")
		}
		got = k
		return nil
	}); err != nil {
		t.Fatalf("GetUserKey: %v", err)
	}

	if got.Fingerprint != "ABCDEF0123456789" {
		t.Errorf("fingerprint = %q", got.Fingerprint)
	}
	// BYTE-FOR-BYTE. This column is served verbatim over WKD, so "equivalent"
	// is not good enough — a round trip that re-encoded would break every
	// signature check on the far side while looking fine here.
	if !bytes.Equal(got.PublicKey, pub) {
		t.Errorf("the public key did not survive the round trip byte-for-byte (%d bytes in, %d out)",
			len(pub), len(got.PublicKey))
	}
	if string(got.PrivateKeyCT) != string(sealed) {
		t.Errorf("sealed private key did not survive the round trip: %x", got.PrivateKeyCT)
	}
	if got.EnvelopeVer != 1 {
		t.Errorf("envelope_ver = %d, want 1", got.EnvelopeVer)
	}
	if got.CreatedAt.IsZero() {
		t.Error("created_at was not set")
	}

	// ⚠ dek_id must be NULL for a pgp row (ADR-024, migration 00030). If a
	// future change starts writing it, the sealing scheme has quietly changed
	// back to the master-key hierarchy — which is the one thing about this
	// table that must not drift silently.
	var dekID *string
	if err := h.super.QueryRow(ctx,
		`SELECT dek_id FROM app.user_keys WHERE id = $1`, keyID.String()).Scan(&dekID); err != nil {
		t.Fatalf("read dek_id: %v", err)
	}
	if dekID != nil {
		t.Errorf("dek_id = %q, want NULL: pgp keys are sealed under the crypto process's own root, "+
			"not under a stored DEK (ADR-024)", *dekID)
	}
}

// TestUserKeyIsInvisibleToAnotherUser covers the STORE API: whatever the caller
// names, the key layer returns nothing that is not theirs.
//
// ⚠ It does NOT prove that RLS is what does this, and a probe showed why: with
// RLS bypassed entirely (reading as the superuser) it still passes, because
// GetUserKey's own `WHERE user_id = $1` is sufficient on its own. That is a
// perfectly good belt — but the braces are proved separately, without a
// user_id predicate, in TestUserKeyRLSHidesTheRowNotJustTheQuery below.
//
// The service-level check is proved in internal/pgpkeyd, against a vault that
// does not filter, so that deleting it turns a test red.
func TestUserKeyIsInvisibleToAnotherUser(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()
	a, b := seedTwoUsers(t, h.super)
	s := h.appStore()

	aID, bID := ulid.MustParse(a.ID), ulid.MustParse(b.ID)
	keyID := NewULID()

	if err := s.UserTx(ctx, aID, func(tx *UserTx) error {
		_, err := tx.InsertUserKey(ctx, UserKey{
			ID: keyID, UserID: aID, Kind: KeyPGP,
			Fingerprint: "FEEDFACE" + keyID.String(),
			PublicKey:   realPublicKey(t, "fixture@example.com"), PrivateKeyCT: []byte{0xAA},
		})
		return err
	}); err != nil {
		t.Fatalf("seed A's key: %v", err)
	}

	// POSITIVE CONTROL. Without it, a store that found nothing for anyone would
	// pass the negative assertion below and look perfectly isolated.
	if err := s.UserTx(ctx, aID, func(tx *UserTx) error {
		if _, found, err := tx.GetUserKey(ctx, keyID); err != nil {
			return err
		} else if !found {
			t.Error("A cannot read A's own key — the negative test below would prove nothing")
		}
		return nil
	}); err != nil {
		t.Fatalf("positive control: %v", err)
	}

	// The refusal: B naming A's key id by exact ULID.
	if err := s.UserTx(ctx, bID, func(tx *UserTx) error {
		k, found, err := tx.GetUserKey(ctx, keyID)
		if err != nil {
			return err
		}
		if found {
			t.Errorf("B read A's key row: fingerprint %q, %d sealed bytes",
				k.Fingerprint, len(k.PrivateKeyCT))
		}
		return nil
	}); err != nil {
		t.Fatalf("cross-user read: %v", err)
	}

	// And B cannot see it in a list either — a filter applied on read-by-id but
	// not on enumeration would be a plausible and useless half-fix.
	if err := s.UserTx(ctx, bID, func(tx *UserTx) error {
		keys, err := tx.ListUserKeys(ctx)
		if err != nil {
			return err
		}
		for _, k := range keys {
			if k.ID.Compare(keyID) == 0 {
				t.Error("A's key appeared in B's key list")
			}
		}
		return nil
	}); err != nil {
		t.Fatalf("cross-user list: %v", err)
	}
}

// TestInsertUserKeyAppendsChangeLog holds the load-bearing invariant: every
// mutation of a JMAP-visible object appends a change_log row in the same
// transaction. 'Key' has been in the app.object_type enum since the baseline
// and this is the first code to write one.
func TestInsertUserKeyAppendsChangeLog(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()
	a, _ := seedTwoUsers(t, h.super)
	s := h.appStore()

	userID := ulid.MustParse(a.ID)
	keyID := NewULID()

	before := countChanges(t, h, a.ID, "Key")
	if err := s.UserTx(ctx, userID, func(tx *UserTx) error {
		_, err := tx.InsertUserKey(ctx, UserKey{
			ID: keyID, UserID: userID, Kind: KeyPGP,
			Fingerprint: "CAFEBABE" + keyID.String(),
			PublicKey:   realPublicKey(t, "fixture@example.com"), PrivateKeyCT: []byte{0xBB},
		})
		return err
	}); err != nil {
		t.Fatalf("InsertUserKey: %v", err)
	}
	if after := countChanges(t, h, a.ID, "Key"); after != before+1 {
		t.Errorf("Key change_log rows: %d -> %d, want exactly one appended", before, after)
	}
}

// TestBindKeyToIdentityAppendsBothChangeRows is the case most likely to be got
// wrong. Binding reads as "a key change", and it is also a mutation of
// app.identities — a JMAP-visible object that every client syncs through
// /changes. One row would leave clients showing an identity whose default key
// silently moved.
func TestBindKeyToIdentityAppendsBothChangeRows(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()
	a, _ := seedTwoUsers(t, h.super)
	s := h.appStore()

	userID := ulid.MustParse(a.ID)
	identityID := ulid.MustParse(a.IdentityID)
	keyID := NewULID()

	if err := s.UserTx(ctx, userID, func(tx *UserTx) error {
		_, err := tx.InsertUserKey(ctx, UserKey{
			ID: keyID, UserID: userID, Kind: KeyPGP,
			Fingerprint: "D00DFEED" + keyID.String(),
			PublicKey:   realPublicKey(t, "fixture@example.com"), PrivateKeyCT: []byte{0xCC},
		})
		return err
	}); err != nil {
		t.Fatalf("InsertUserKey: %v", err)
	}

	keyBefore := countChanges(t, h, a.ID, "Key")
	idBefore := countChanges(t, h, a.ID, "Identity")

	if err := s.UserTx(ctx, userID, func(tx *UserTx) error {
		bound, err := tx.BindKeyToIdentity(ctx, keyID, identityID)
		if err != nil {
			return err
		}
		if !bound {
			t.Fatal("binding reported not-found for the user's own key and identity")
		}
		return nil
	}); err != nil {
		t.Fatalf("BindKeyToIdentity: %v", err)
	}

	if got := countChanges(t, h, a.ID, "Key"); got != keyBefore+1 {
		t.Errorf("Key change_log rows: %d -> %d, want one appended", keyBefore, got)
	}
	if got := countChanges(t, h, a.ID, "Identity"); got != idBefore+1 {
		t.Errorf("Identity change_log rows: %d -> %d, want one appended — binding moves "+
			"app.identities.default_key_id, which clients sync", idBefore, got)
	}

	// Both sides of the binding, or it is not a binding.
	var storedKey *string
	if err := h.super.QueryRow(ctx,
		`SELECT default_key_id FROM app.identities WHERE id = $1`, identityID.String()).Scan(&storedKey); err != nil {
		t.Fatalf("read identity: %v", err)
	}
	if storedKey == nil || *storedKey != keyID.String() {
		t.Errorf("identities.default_key_id = %v, want %s", storedKey, keyID)
	}
	var storedIdentity *string
	if err := h.super.QueryRow(ctx,
		`SELECT identity_id FROM app.user_keys WHERE id = $1`, keyID.String()).Scan(&storedIdentity); err != nil {
		t.Fatalf("read key: %v", err)
	}
	if storedIdentity == nil || *storedIdentity != identityID.String() {
		t.Errorf("user_keys.identity_id = %v, want %s", storedIdentity, identityID)
	}
}

// TestBindKeyToIdentityRefusesAnotherUsersIdentity: RLS scopes the identity
// update, so a foreign identity id binds nothing rather than reaching across.
func TestBindKeyToIdentityRefusesAnotherUsersIdentity(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()
	a, b := seedTwoUsers(t, h.super)
	s := h.appStore()

	userID := ulid.MustParse(a.ID)
	keyID := NewULID()
	if err := s.UserTx(ctx, userID, func(tx *UserTx) error {
		_, err := tx.InsertUserKey(ctx, UserKey{
			ID: keyID, UserID: userID, Kind: KeyPGP,
			Fingerprint: "BAADF00D" + keyID.String(),
			PublicKey:   realPublicKey(t, "fixture@example.com"), PrivateKeyCT: []byte{0xDD},
		})
		return err
	}); err != nil {
		t.Fatalf("InsertUserKey: %v", err)
	}

	if err := s.UserTx(ctx, userID, func(tx *UserTx) error {
		bound, err := tx.BindKeyToIdentity(ctx, keyID, ulid.MustParse(b.IdentityID))
		if err != nil {
			return err
		}
		if bound {
			t.Error("A bound A's key to B's identity")
		}
		return nil
	}); err != nil {
		t.Fatalf("cross-user bind: %v", err)
	}

	var storedKey *string
	if err := h.super.QueryRow(ctx,
		`SELECT default_key_id FROM app.identities WHERE id = $1`, b.IdentityID).Scan(&storedKey); err != nil {
		t.Fatalf("read B's identity: %v", err)
	}
	if storedKey != nil {
		t.Errorf("B's identity gained a default key: %s", *storedKey)
	}

	// ⚠ AND THE OTHER SIDE, which this test originally forgot to look at — the
	// omission that let a half-applied binding survive review. A refused
	// binding must leave A's key untouched too; a key row pointing at another
	// user's identity is exactly what a partially-applied write would produce,
	// and nothing about B's identity row would reveal it.
	var storedIdentity *string
	if err := h.super.QueryRow(ctx,
		`SELECT identity_id FROM app.user_keys WHERE id = $1`, keyID.String()).Scan(&storedIdentity); err != nil {
		t.Fatalf("read A's key: %v", err)
	}
	if storedIdentity != nil {
		t.Errorf("A's key was bound to %s despite the binding being refused — half-applied write", *storedIdentity)
	}
}

// TestUserKeyRLSHidesTheRowNotJustTheQuery answers a question the test above
// CANNOT: is row-level security doing anything here at all?
//
// GetUserKey's SQL carries its own `WHERE user_id = $1`, so a cross-user read
// through it returns nothing whether or not RLS exists. A probe confirmed
// exactly that — reading as the superuser, with RLS bypassed, still found
// nothing, because the predicate alone explained the result. The property was
// true; the mechanism named in the comment was unproven.
//
// So this test asks the question directly, with NO user_id predicate in the
// query, and carries its own positive control:
//
//	as mailroom_app (RLS enforced)   -> must find nothing
//	as the superuser (RLS bypassed)  -> must find the row
//
// The second half is what makes the first half mean something. Without it,
// "found nothing" could equally be "the row was never written".
func TestUserKeyRLSHidesTheRowNotJustTheQuery(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()
	a, b := seedTwoUsers(t, h.super)

	aID := ulid.MustParse(a.ID)
	keyID := NewULID()
	if err := h.appStore().UserTx(ctx, aID, func(tx *UserTx) error {
		_, err := tx.InsertUserKey(ctx, UserKey{
			ID: keyID, UserID: aID, Kind: KeyPGP,
			Fingerprint: "5EC12E7E" + keyID.String(),
			PublicKey:   realPublicKey(t, "fixture@example.com"), PrivateKeyCT: []byte{0xFF},
		})
		return err
	}); err != nil {
		t.Fatalf("seed A's key: %v", err)
	}

	// No user_id predicate anywhere: the only thing that can filter this is RLS.
	const byIDOnly = `SELECT count(*) FROM app.user_keys WHERE id = $1`

	// POSITIVE CONTROL: the row exists and this query finds it when RLS is not
	// in the way.
	var superCount int
	if err := h.super.QueryRow(ctx, byIDOnly, keyID.String()).Scan(&superCount); err != nil {
		t.Fatalf("superuser read: %v", err)
	}
	if superCount != 1 {
		t.Fatalf("superuser sees %d rows, want 1 — the row was never written, so the "+
			"negative assertion below would prove nothing", superCount)
	}

	// THE ASSERTION: as B, under RLS, the same predicate must find nothing.
	conn, err := h.app.Acquire(ctx)
	if err != nil {
		t.Fatalf("acquire app conn: %v", err)
	}
	defer conn.Release()
	if _, err := conn.Exec(ctx, `SELECT set_config('mailroom.user_id', $1, false)`, b.ID); err != nil {
		t.Fatalf("set user: %v", err)
	}
	var appCount int
	if err := conn.QueryRow(ctx, byIDOnly, keyID.String()).Scan(&appCount); err != nil {
		t.Fatalf("app read as B: %v", err)
	}
	if appCount != 0 {
		t.Errorf("B sees %d of A's key rows through a query with no user_id predicate — "+
			"RLS is not filtering app.user_keys", appCount)
	}

	// And as A, the same query must find it: RLS filters by owner, it does not
	// simply hide the table.
	if _, err := conn.Exec(ctx, `SELECT set_config('mailroom.user_id', $1, false)`, a.ID); err != nil {
		t.Fatalf("set user: %v", err)
	}
	var ownerCount int
	if err := conn.QueryRow(ctx, byIDOnly, keyID.String()).Scan(&ownerCount); err != nil {
		t.Fatalf("app read as A: %v", err)
	}
	if ownerCount != 1 {
		t.Errorf("A sees %d of A's own key rows, want 1 — RLS is refusing everyone, "+
			"which would make the assertion above vacuous", ownerCount)
	}
}

// TestInsertUserKeyRejectsDuplicateFingerprint: importing the same key twice is
// a no-op the caller reports, not a crash.
func TestInsertUserKeyRejectsDuplicateFingerprint(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()
	a, _ := seedTwoUsers(t, h.super)
	s := h.appStore()

	userID := ulid.MustParse(a.ID)
	fpr := "DEADBEEF" + NewULID().String()

	insert := func() error {
		return s.UserTx(ctx, userID, func(tx *UserTx) error {
			_, err := tx.InsertUserKey(ctx, UserKey{
				ID: NewULID(), UserID: userID, Kind: KeyPGP,
				Fingerprint: fpr, PublicKey: realPublicKey(t, "fixture@example.com"), PrivateKeyCT: []byte{0xEE},
			})
			return err
		})
	}
	if err := insert(); err != nil {
		t.Fatalf("first insert: %v", err)
	}
	err := insert()
	if err == nil {
		t.Fatal("the same fingerprint was stored twice")
	}
	if !errors.Is(err, ErrFingerprintTaken) {
		t.Errorf("err = %v, want ErrFingerprintTaken — the caller cannot tell "+
			"'already have it' from a real failure", err)
	}
}

func countChanges(t *testing.T, h *harness, userID, objectType string) int {
	t.Helper()
	var n int
	if err := h.super.QueryRow(context.Background(),
		`SELECT count(*) FROM app.change_log WHERE user_id = $1 AND object_type = $2`,
		userID, objectType).Scan(&n); err != nil {
		t.Fatalf("count change_log(%s): %v", objectType, err)
	}
	return n
}

// TestSigningKeyForIdentity covers the read the send path uses to decide
// whether a message gets signed at all.
//
// Every negative case here is a key that MUST NOT sign, and each would fail
// differently and later if this returned it: a retired key produces a signature
// correspondents are told to distrust, a revoked one the same, and a
// public-only row fails at the far side of the crypto boundary at send time,
// which is the worst place to find out.
func TestSigningKeyForIdentity(t *testing.T) {
	h := newHarness(t)
	ctx := context.Background()
	a, b := seedTwoUsers(t, h.super)
	s := h.appStore()

	userID := ulid.MustParse(a.ID)
	identityID := ulid.MustParse(a.IdentityID)

	// No key bound yet: "do not sign" is the ordinary case and not an error.
	if err := s.UserTx(ctx, userID, func(tx *UserTx) error {
		k, found, err := tx.SigningKeyForIdentity(ctx, identityID)
		if err != nil {
			return err
		}
		if found {
			t.Errorf("found a signing key %s for an identity with none bound", k.ID)
		}
		return nil
	}); err != nil {
		t.Fatalf("unbound identity: %v", err)
	}

	keyID := seedPublishableKey(t, s, userID, identityID)

	// POSITIVE CONTROL. Without it every negative below could pass because the
	// function never finds anything at all.
	if err := s.UserTx(ctx, userID, func(tx *UserTx) error {
		k, found, err := tx.SigningKeyForIdentity(ctx, identityID)
		if err != nil {
			return err
		}
		if !found {
			t.Fatal("a bound, usable key was not found — every assertion below would be vacuous")
		}
		if k.ID.Compare(keyID) != 0 {
			t.Errorf("found key %s, want %s", k.ID, keyID)
		}
		if len(k.PrivateKeyCT) == 0 {
			t.Error("the signing key came back with no sealed private half — it cannot sign")
		}
		return nil
	}); err != nil {
		t.Fatalf("positive control: %v", err)
	}

	// Another user's identity id: RLS, not a comparison, but it must hold.
	if err := s.UserTx(ctx, ulid.MustParse(b.ID), func(tx *UserTx) error {
		if _, found, err := tx.SigningKeyForIdentity(ctx, identityID); err != nil {
			return err
		} else if found {
			t.Error("B found a signing key for A's identity")
		}
		return nil
	}); err != nil {
		t.Fatalf("cross-user: %v", err)
	}

	for _, tc := range []struct {
		name string
		sql  string
	}{
		{"retired", `UPDATE app.user_keys SET decrypt_only = true WHERE id = $1`},
		{"revoked", `UPDATE app.user_keys SET decrypt_only = false, revoked_at = now() WHERE id = $1`},
		{"public-only", `UPDATE app.user_keys SET revoked_at = NULL, private_key_ct = NULL WHERE id = $1`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := h.super.Exec(ctx, tc.sql, keyID.String()); err != nil {
				t.Fatalf("mutate: %v", err)
			}
			if err := s.UserTx(ctx, userID, func(tx *UserTx) error {
				if _, found, err := tx.SigningKeyForIdentity(ctx, identityID); err != nil {
					return err
				} else if found {
					t.Errorf("a %s key was offered as a signing key", tc.name)
				}
				return nil
			}); err != nil {
				t.Fatalf("%s: %v", tc.name, err)
			}
		})
	}
}
